```vue src/components/document/ChapterBlock.vue
<script setup>
import MarkdownViewer from '../MarkdownViewer.vue'
import Code from '../Code.vue'
import ChapterBlock from './ChapterBlock.vue'
import BlockEditor from '../BlockEditor.vue'
import parser from '@/utils/markdownParser'
</script>

<template>
  <div 
    class="chapter-block transition-all duration-200 mb-4"
    @mouseenter="isHovered = true"
    @mouseleave="isHovered = false"
  >
    <!-- Chapter header with copy button -->
    <div v-if="chapter.level > 0">
      <div class="flex items-center justify-between group/header">
        <div :class="'heading-' + chapter.level">
          <h1 v-if="chapter.level === 1" class="text-3xl font-bold">{{ chapter.title }}</h1>
          <h2 v-else-if="chapter.level === 2" class="text-2xl font-bold">{{ chapter.title }}</h2>
          <h3 v-else-if="chapter.level === 3" class="text-xl font-bold">{{ chapter.title }}</h3>
          <h4 v-else-if="chapter.level === 4" class="text-lg font-bold">{{ chapter.title }}</h4>
          <h5 v-else-if="chapter.level === 5" class="font-bold">{{ chapter.title }}</h5>
          <h6 v-else class="font-bold text-sm">{{ chapter.title }}</h6>
        </div>
        <div class="hidden group-hover/header:flex gap-2 items-center">
          <slot 
            name="chapter-actions" 
            :chapter="chapter"
            :full-content="fullChapterContent"
          >
            <button
              class="btn btn-sm btn-ghost gap-2"
              @click="copyChapterMarkdown"
              :title="'Copy chapter: ' + chapter.title"
            >
              <i class="fa-solid fa-copy"></i>
              Copy
            </button>
            <button
              class="btn btn-sm btn-ghost gap-2"
              @click="createTaskFromChapter"
              :title="'Create task from chapter: ' + chapter.title"
            >
              <i class="fa-solid fa-plus"></i> Task
            </button>
          </slot>
        </div>
      </div>
    </div>

    <!-- Render blocks within chapter -->
    <div class="space-y-4">
      <div v-for="block in blocks" :key="block.hash" class="relative group/block">
        <!-- Edit button overlay -->
        <div class="absolute -left-10 top-2 opacity-0 group-hover/block:opacity-100 transition-opacity z-10">
          <button
            v-if="!editingBlockHash || editingBlockHash !== block.hash"
            class="btn btn-xs btn-ghost tooltip tooltip-right"
            data-tip="Edit block"
            @click="startEditBlock(block)"
          >
            <i class="fa-solid fa-pen"></i>
          </button>
        </div>

        <!-- Editing state -->
        <div v-if="editingBlockHash === block.hash" class="bg-base-200 rounded-lg p-3 border border-base-300">
          <div class="flex items-center justify-between gap-2 mb-2 pb-2 border-b border-base-300">
            <span class="text-xs font-semibold text-base-content/60">Editing block</span>
            <div class="flex gap-1">
              <button
                class="btn btn-xs btn-ghost gap-1"
                @click="cancelEditBlock"
              >
                <i class="fa-solid fa-ban"></i> Cancel
              </button>
              <button
                class="btn btn-xs btn-primary gap-1"
                :disabled="!hasBlockChanges(block)"
                @click="saveBlockEdit(block)"
              >
                <i class="fa-solid fa-check"></i> Save
              </button>
            </div>
          </div>
          <div class="bg-base-300 rounded min-h-[200px] overflow-hidden">
            <textarea
              v-model="editedBlockContent"
              class="w-full h-[300px] p-3 bg-base-300 text-sm font-mono text-base-content border-0 resize-none focus:outline-none"
              :placeholder="'Edit ' + (isCodeBlock(block) ? 'code' : 'markdown') + '...'"
            ></textarea>
          </div>
          <div class="mt-2 text-[10px] text-base-content/40">
            <span v-if="hasBlockChanges(block)" class="text-warning">
              <i class="fa-solid fa-circle-info"></i> Unsaved changes
            </span>
            <span>{{ editedBlockContent.length }} characters</span>
          </div>
        </div>

        <!-- Normal view -->
        <template v-else>
          <!-- Code block -->
          <Code
            v-if="isCodeBlock(block)"
            :text="block.content"
            :text-language="block.type"
            :fileName="block.fileName"
            :files="files"
            :project="docProject"
            :finished="block.finished"
            :loading="loading"
            :chat="chat"
            :message="message"
            :block-hash="block.hash"
            @generate-code="$emit('generate-code', $event)"
            @reload-file="$emit('reload-file', $event)"
            @open-file="$emit('open-file', $event)"
            @save-file="$emit('save-file', $event)"
            @add-file="$emit('add-file', $event)"
            @edit-message="$emit('edit-message', $event)"
            @sub-task="onCodeSubTask"
            @block-edited="onBlockEdited"
          />

          <!-- Markdown block -->
          <MarkdownViewer
            v-else
            :files="files"
            :documentId="documentId"
            :text="block.content"
            @add-file="$emit('add-file', $event)"
            @copy-chapter="$emit('copy-chapter', $event)"
            @create-task="onCreateTask"
          />
        </template>
      </div>
    </div>

    <!-- Render child chapters -->
    <div v-if="chapter.children && chapter.children.length">
      <ChapterBlock
        v-for="childChapter in chapter.children"
        :key="childChapter.hash"
        :chapter="childChapter"
        :blocks="getChildChapterBlocks(childChapter)"
        :files="files"
        :documentId="documentId"
        :docProject="docProject"
        :loading="loading"
        :chat="chat"
        :message="message"
        @add-file="$emit('add-file', $event)"
        @copy-chapter="handleChildCopy"
        @create-task="onCreateTask"
        @generate-code="$emit('generate-code', $event)"
        @reload-file="$emit('reload-file', $event)"
        @open-file="$emit('open-file', $event)"
        @save-file="$emit('save-file', $event)"
        @edit-message="$emit('edit-message', $event)"
        @sub-task="$emit('sub-task', $event)"
        @block-edited="onBlockEdited"
      >
        <template #chapter-actions="{ chapter: childChapter, fullContent }">
          <slot 
            name="chapter-actions" 
            :chapter="childChapter"
            :full-content="fullContent"
          />
        </template>
      </ChapterBlock>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    chapter: { type: Object, required: true },
    blocks: { type: Array, required: true },
    files: { type: Array, default: null },
    documentId: { type: String, default: '' },
    docProject: { type: Object, default: null },
    loading: { type: Boolean, default: false },
    chat: { type: Object, default: null },
    message: { type: Object, default: null }
  },
  emits: [
    'add-file',
    'copy-chapter',
    'create-task',
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'edit-message',
    'sub-task',
    'block-edited'
  ],
  data() {
    return {
      isHovered: false,
      editingBlockHash: null,
      editedBlockContent: '',
      originalBlockContent: ''
    }
  },
  computed: {
    fullChapterContent() {
      return parser.collectAllChildContent(this.chapter)
    }
  },
  methods: {
    getChildChapterBlocks(childChapter) {
      const contentWithoutHeader = parser.stripHeaderFromContent(childChapter.content || '')
      return parser.parseChildBlocks(contentWithoutHeader, parser.getRenderer)
    },
    isCodeBlock(block) {
      return !!block.fileName
    },
    startEditBlock(block) {
      this.editingBlockHash = block.hash
      this.editedBlockContent = block.content
      this.originalBlockContent = block.content
    },
    cancelEditBlock() {
      this.editingBlockHash = null
      this.editedBlockContent = ''
      this.originalBlockContent = ''
    },
    hasBlockChanges(block) {
      return this.editedBlockContent !== this.originalBlockContent
    },
    saveBlockEdit(block) {
      if (!this.hasBlockChanges(block)) {
        this.cancelEditBlock()
        return
      }

      this.$emit('block-edited', {
        blockHash: block.hash,
        originalContent: this.originalBlockContent,
        newContent: this.editedBlockContent,
        block
      })

      this.editingBlockHash = null
      this.editedBlockContent = ''
      this.originalBlockContent = ''
    },
    onBlockEdited(data) {
      this.$emit('block-edited', data)
    },
    copyChapterMarkdown() {
      const fullContent = this.fullChapterContent
      navigator.clipboard.writeText(fullContent).then(() => {
        this.$emit('copy-chapter', {
          title: this.chapter.title,
          content: fullContent,
          level: this.chapter.level
        })
      }).catch(err => {
        console.error('Failed to copy chapter markdown', err)
      })
    },
    createTaskFromChapter() {
      const fullContent = this.fullChapterContent
      this.$emit('create-task', {
        title: this.chapter.title,
        content: fullContent
      })
    },
    handleChildCopy(chapterData) {
      this.$emit('copy-chapter', chapterData)
    },
    onCreateTask(taskData) {
      this.$emit('create-task', taskData)
    },
    onCodeSubTask(subTaskData) {
      this.$emit('create-task', {
        title: subTaskData.file ? subTaskData.file.split('/').reverse()[0] : '',
        content: subTaskData.content || ''
      })
    }
  }
}
</script>
