<script>
export default {
  props: {
    content: { type: String, default: '' },
    files: { type: Array, default: null },
    project: { type: Object, default: null },
    chat: { type: Object, default: null },
    loading: { type: Boolean, default: false },
    documentId: { type: String, default: '' },
    message: { type: Object, default: null }
  },
  emits: [
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'add-file',
    'edit-message',
    'sub-task',
    'copy-chapter',
    'create-task',
    'block-edited'
  ],
  data() {
    return {
      cachedChapters: [],
      lastContentHash: null
    }
  },
  computed: {
    chapters() {
      const contentHash = this.getContentHash()

      if (this.lastContentHash !== null && contentHash === this.lastContentHash && !this.loading) {
        return this.cachedChapters
      }

      this.lastContentHash = contentHash
      this.cachedChapters = parser.parseChapters(this.content || '', this.loading)
      return this.cachedChapters
    },
    docProject() {
      return this.project || this.$project
    }
  },
  methods: {
    getContentHash() {
      const content = this.content || ''
      let hash = 0
      for (let i = 0; i < content.length; i++) {
        const char = content.charCodeAt(i)
        hash = ((hash << 5) - hash) + char
        hash = hash & hash
      }
      return hash.toString()
    },
    getChapterBlocks(chapter) {
      const contentWithoutHeader = parser.stripHeaderFromContent(chapter.content || '')
      return parser.parseBlocks(contentWithoutHeader, parser.getRenderer, chapter.level)
    },
    handleCopyLevel({ level }, startIndex) {
      const collectedContent = []

      for (let i = startIndex; i < this.chapters.length; i++) {
        const chapter = this.chapters[i]

        if (i > startIndex && chapter.level <= level) {
          break
        }

        collectedContent.push(chapter.content)
      }

      const fullContent = collectedContent.join('\n\n')
      navigator.clipboard.writeText(fullContent).then(() => {
        this.$emit('copy-chapter', {
          title: this.chapters[startIndex].title,
          content: fullContent,
          level: level
        })
      }).catch(err => {
        console.error('Failed to copy chapter markdown', err)
      })
    },
    handleCreateTask(taskData) {
      this.$emit('create-task', taskData)
    },
    handleBlockEdited(editData) {
      this.$emit('block-edited', editData)
    }
  }
}
</script>
