<script setup>
import ChapterBlock from './ChapterBlock.vue'
import ChapterMenu from './ChapterMenu.vue'
import parser from '@/utils/markdownParser'
</script>

<template>
  <div class="flex flex-col @container/document">
    <div
      v-for="(chapter, index) in chapters"
      :key="chapter.hash || ('chapter-' + chapter.level + '-' + index)"
      @mouseenter="hoveredChapterId = chapter.hash"
      @mouseleave="hoveredChapterId = null"
    >
      <!-- Chapter Menu (shown on hover) -->
      <ChapterMenu
        v-if="hoveredChapterId === chapter.hash && editingChapterId !== chapter.hash"
        :chapter="chapter"
        @edit="startEditingChapter(chapter)"
        @copy="copyChapterContent(chapter)"
        @create-task="createTaskFromChapter(chapter)"
      >
        <template #chapter-actions="{ chapter: ch, fullContent }">
          <slot 
            name="chapter-actions" 
            :chapter="ch"
            :full-content="fullContent"
          />
        </template>
      </ChapterMenu>

      <!-- Chapter Block (with or without edit mode) -->
      <ChapterBlock
        :chapter="chapter"
        :blocks="getChapterBlocks(chapter)"
        :files="files"
        :documentId="documentId"
        :docProject="docProject"
        :chat="chat"
        :message="message"
        :loading="loading"
        :is-editing="editingChapterId === chapter.hash"
        :edited-content="editingChapterId === chapter.hash ? editedContent : ''"
        @add-file="$emit('add-file', $event)"
        @copy-chapter="handleCopyChapter"
        @create-task="handleCreateTask"
        @generate-code="$emit('generate-code', $event)"
        @reload-file="$emit('reload-file', { file: $event, message })"
        @open-file="$emit('open-file', $event)"
        @save-file="$emit('save-file', $event)"
        @edit-message="$emit('edit-message', $event)"
        @sub-task="$emit('sub-task', $event)"
        @edit-cancel="cancelEdit"
        @edit-save="saveEdit"
      >
        <template #chapter-actions="{ chapter: ch, fullContent }">
          <slot 
            name="chapter-actions" 
            :chapter="ch"
            :full-content="fullContent"
          />
        </template>
      </ChapterBlock>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    content: { type: String, default: '' },
    files: { type: Array, default: null },
    project: { type: Object, default: null },
    chat: { type: Object, default: null },
    loading: { type: Boolean, default: false },
    documentId: { type: String, default: '' },
    message: { type: Object, default: null }
  },
  emits: [
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'add-file',
    'edit-message',
    'sub-task',
    'copy-chapter',
    'create-task',
    'block-edited',
    'change'
  ],
  data() {
    return {
      cachedChapters: [],
      lastContentHash: null,
      hoveredChapterId: null,
      editingChapterId: null,
      editedContent: '',
      originalContent: ''
    }
  },
  computed: {
    chapters() {
      const contentHash = this.getContentHash()

      if (this.lastContentHash !== null && contentHash === this.lastContentHash && !this.loading) {
        return this.cachedChapters
      }

      this.lastContentHash = contentHash
      this.cachedChapters = parser.parseChapters(this.content || '', this.loading)
      return this.cachedChapters
    },
    docProject() {
      return this.project || this.$project
    }
  },
  methods: {
    getContentHash() {
      const content = this.content || ''
      let hash = 0
      for (let i = 0; i < content.length; i++) {
        const char = content.charCodeAt(i)
        hash = ((hash << 5) - hash) + char
        hash = hash & hash
      }
      return hash.toString()
    },
    getChapterBlocks(chapter) {
      const contentWithoutHeader = parser.stripHeaderFromContent(chapter.content || '')
      return parser.parseBlocks(contentWithoutHeader, parser.getRenderer)
    },
    startEditingChapter(chapter) {
      this.editingChapterId = chapter.hash
      this.originalContent = parser.collectAllChildContent(chapter)
      this.editedContent = this.originalContent
    },
    cancelEdit() {
      this.editingChapterId = null
      this.editedContent = ''
      this.originalContent = ''
    },
    saveEdit() {
      if (this.editedContent === this.originalContent) {
        this.cancelEdit()
        return
      }

      const updatedContent = parser.updateBlockInContent(
        this.content,
        this.originalContent,
        this.editedContent
      )

      this.$emit('change', updatedContent)
      this.$emit('block-edited', {
        originalContent: this.originalContent,
        newContent: this.editedContent,
        fullContent: updatedContent
      })

      this.cancelEdit()
    },
    copyChapterContent(chapter) {
      const fullContent = parser.collectAllChildContent(chapter)
      this.$ui.copyTextToClipboard(fullContent)
      this.$emit('copy-chapter', {
        title: chapter.title,
        content: fullContent,
        level: chapter.level
      })
    },
    createTaskFromChapter(chapter) {
      const fullContent = parser.collectAllChildContent(chapter)
      this.$emit('create-task', {
        title: chapter.title,
        content: fullContent
      })
    },
    handleCopyChapter(chapterData) {
      this.$emit('copy-chapter', chapterData)
    },
    handleCreateTask(taskData) {
      this.$emit('create-task', taskData)
    }
  }
}
</script>
